var n_rain = 400;
var c_rain,ctx_rain,cw_rain,ch_rain,duration_rain,img_rain,particles_rain,particleNumber_rain,Particle_rain = null;

function setParticle(p) {
    particleNumber_rain++;
    var _dur = rand(duration_rain/2, duration_rain),
        _tl = new TimelineMax()
            .fromTo(p, _dur, {
                x:rand(-p.size, cw_rain+ch_rain/2),
                y:-p.size
            },{
                x:'-='+rand(ch_rain/2-50,ch_rain/2),
                y:ch_rain+p.size,
                ease:Power0.easeNone,
                onComplete:function(){ setParticle(p); }
            });
    if (particleNumber_rain<n_rain) _tl.seek(_dur*rand());
}

function init_rain() {
    c_rain = document.getElementsByClassName("rain_effect")[0],
        ctx_rain = c_rain.getContext("2d"),
        cw_rain = (c_rain.width = window.innerWidth),
        ch_rain = (c_rain.height = window.innerHeight),
        duration_rain = ch_rain/850,
        img_rain = new Image(),
        particles_rain = [],
        particleNumber_rain = 0,
        Particle_rain = function() {
            this.alpha = rand(0.1, 0.4);
            this.size = rand(60, 70);
            this.draw = function() {
                ctx_rain.globalAlpha = this.alpha;
                ctx_rain.drawImage(img_rain, this.x, this.y, this.size, this.size);
            }
        };
    for (var i=0; i<n_rain; i++) {
        particles_rain.push(new Particle_rain());
        setParticle(particles_rain[i]);
    }
    TweenMax.ticker.addEventListener("tick", function(){
        ctx_rain.clearRect(0, 0, cw_rain, ch_rain);
        for (var i=0; i<n_rain; i++) {
            particles_rain[i].draw();
        }
    });
    window.addEventListener('resize', function() {
        try {
            particleNumber_rain = 0;
            cw_rain = (c_rain.width = window.innerWidth);
            ch_rain = (c_rain.height = window.innerHeight);
            for (var i=0; i<n_rain; i++) {
                TweenMax.killTweensOf(particles_rain[i]);
                setParticle(particles_rain[i]);
            }
        } catch (e) {}
    });
    img_rain.src = "data:image/png;base64,";
}

function rand(min=0, max=1) {
    return min + (max-min)*Math.random();
}

var c_snow,ctx_snow,w_snow,h_snow,req_snow;

window.addEventListener('resize', function(){
    try {
        c_snow.width = w_snow = window.innerWidth;
        c_snow.height = h_snow = window.innerHeight;
    } catch (e) {}
}, false);

function init_snow() {
    c_snow = document.getElementsByClassName('snow_effect')[0],
        ctx_snow = c_snow.getContext("2d");
    w_snow = c_snow.width = window.innerWidth,
        h_snow = c_snow.height = window.innerHeight;
    var snow, arr = [];
    var num = 400, tsc = 1, sp = 1;
    var sc = 1.3, t = 0, mv = 20, min = 1;
    for (var i = 0; i < num; ++i) {
        snow = new Flake();
        snow.y = Math.random() * (h_snow + 50);
        snow.x = Math.random() * w_snow;
        snow.t = Math.random() * (Math.PI * 2);
        snow.sz = (100 / (10 + (Math.random() * 100))) * sc;
        snow.sp = (Math.pow(snow.sz * .8, 2) * .15) * sp;
        snow.sp = snow.sp < min ? min : snow.sp;
        arr.push(snow);
    }
    go();
    function go(){
        req_snow = window.requestAnimationFrame(go);
        ctx_snow.clearRect(0, 0, w_snow, h_snow);
        ctx_snow.fillRect(0, 0, w_snow, h_snow);
        ctx_snow.fill();
        for (var i = 0; i < arr.length; ++i) {
            f = arr[i];
            f.t += .05;
            f.t = f.t >= Math.PI * 2 ? 0 : f.t;
            f.y += f.sp;
            f.x += Math.sin(f.t * tsc) * (f.sz * .3);
            if (f.y > h_snow + 50) f.y = -10 - Math.random() * mv;
            if (f.x > w_snow + mv) f.x = - mv;
            if (f.x < - mv) f.x = w_snow + mv;
            f.draw();}
    }
    function Flake() {
        this.draw = function() {
            this.g = ctx_snow.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.sz);
            this.g.addColorStop(0, 'hsla(255,255%,255%,1)');
            this.g.addColorStop(1, 'hsla(255,255%,255%,0)');
            ctx_snow.moveTo(this.x, this.y);
            ctx_snow.fillStyle = this.g;
            ctx_snow.beginPath();
            ctx_snow.arc(this.x, this.y, this.sz, 0, Math.PI * 2, true);
            ctx_snow.fill();}
    }
}

var particles_fog = [];
var particleCount_fog = 90;
var maxVelocity = 1.2;
var targetFPS = 30;
var canvasWidth_fog = window.innerWidth;
var canvasHeight_fog = window.innerHeight;
var borderTop = 0.01 * canvasHeight_fog;
var borderBottom = 0.99 * canvasHeight_fog;
var context_fog;

function Particle_fog(context_fog) {
    this.x = 0;
    this.y = 0;
    this.xVelocity = 0;
    this.yVelocity = 0;
    this.radius = 5;
    this.context_fog = context_fog;
    this.draw = function() {
        if (this.image) {
            this.context_fog.drawImage(this.image, this.x - 128, this.y - 128);
            return;
        }
    };
    this.update = function() {
        this.x += this.xVelocity;
        this.y += this.yVelocity;
        if (this.x >= canvasWidth_fog) {
            this.xVelocity = -this.xVelocity;
            this.x = canvasWidth_fog;
        }
        else if (this.x <= 0) {
            this.xVelocity = -this.xVelocity;
            this.x = 0;
        }
        if (this.y >= borderBottom) {
            this.yVelocity = -this.yVelocity;
            this.y = borderBottom;
        }
        else if (this.y <= borderTop) {
            this.yVelocity = -this.yVelocity;
            this.y = borderTop;
        }
    };
    this.setPosition = function(x, y) {
        this.x = x;
        this.y = y;
    };
    this.setVelocity = function(x, y) {
        this.xVelocity = x;
        this.yVelocity = y;
    };
    this.setImage = function(image) {
        this.image = image;
    };
}

function generateRandom(min, max) {
    return Math.random() * (max - min) + min;
}

function draw() {
    context_fog.clearRect( 0, 0, canvasWidth_fog, canvasHeight_fog);
    context_fog.globalAlpha = 0.75;
    context_fog.globalCompositeOperation = 'soft-lights';
    particles_fog.forEach(function(particle) {
        particle.draw();
    });
}

function update() {
    particles_fog.forEach(function(particle) {
        particle.update();
    });
}

function init_fog() {
    var canvas = document.getElementsByClassName('fog_effect')[0];
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    var imageObj_fog = new Image();
    imageObj_fog.onload = function() {
        if (canvas.getContext) {
            context_fog = canvas.getContext('2d');
            for (var i = 0; i < particleCount_fog; ++i) {
                var particle = new Particle_fog(context_fog);
                particle.setPosition(generateRandom(0, canvasWidth_fog), generateRandom(borderTop, borderBottom));
                particle.setVelocity(generateRandom(-maxVelocity, maxVelocity), generateRandom(-maxVelocity, maxVelocity));
                particles_fog.push(particle);
            }
        }
        particles_fog.forEach(function(particle) {
            particle.setImage(imageObj_fog);
        });
        setInterval(function() {
            update();
            draw();
        }, 1000 / targetFPS);
    };
    imageObj_fog.src = "css/Smoke10.png";
}

window.addEventListener("resize", resizecanvas_fireworks_fireworks, false);

window.requestAnimationFrame_fireworks =
    window.requestAnimationFrame       ||
    window.webkitRequestAnimationFrame ||
    window.mozRequestAnimationFrame    ||
    window.oRequestAnimationFrame      ||
    window.msRequestAnimationFrame     ||
    function (callback) {
        window.setTimeout(callback, 1000/60);
    };

var canvas_fireworks, ctx_fireworks, w_fireworks, h_fireworks, particles_fireworks = [], probability = 0.04,
    xPoint, yPoint, req_fireworks;

function init_fireworks() {
    canvas_fireworks = document.getElementsByClassName("fireworks_effect")[0];
    ctx_fireworks = canvas_fireworks.getContext("2d");
    resizecanvas_fireworks_fireworks();
    req_fireworks = window.requestAnimationFrame_fireworks(updateWorld_fireworks);
}

function resizecanvas_fireworks_fireworks() {
    try {
        if (!!canvas_fireworks) {
            w_fireworks = canvas_fireworks.width = window.innerWidth;
            h_fireworks = canvas_fireworks.height = window.innerHeight;
        }
    } catch (e) {}
}

function updateWorld_fireworks() {
    update_fireworks();
    paint_fireworks();
    window.requestAnimationFrame_fireworks(updateWorld_fireworks);
}

function update_fireworks() {
    if (particles_fireworks.length < 500 && Math.random() < probability) {
        createFirework();
    }
    var alive = [];
    for (var i=0; i<particles_fireworks.length; i++) {
        if (particles_fireworks[i].move()) {
            alive.push(particles_fireworks[i]);
        }
    }
    particles_fireworks = alive;
}

function paint_fireworks() {
    ctx_fireworks.globalCompositeOperation = 'source-over';
    ctx_fireworks.clearRect(0, 0, w_fireworks, h_fireworks);
    ctx_fireworks.globalCompositeOperation = 'lighter';
    for (var i=0; i<particles_fireworks.length; i++) {
        particles_fireworks[i].draw(ctx_fireworks);
    }
}

function createFirework() {
    xPoint = Math.random()*(w_fireworks-200)+100;
    yPoint = Math.random()*(h_fireworks-200)+100;
    var nFire = Math.random()*50+100;
    var c = "rgb("+(~~(Math.random()*200+55))+","
        +(~~(Math.random()*200+55))+","+(~~(Math.random()*200+55))+")";
    for (var i=0; i<nFire; i++) {
        var particle = new Particle_fireworks();
        particle.color = c;
        var vy = Math.sqrt(25-particle.vx*particle.vx);
        if (Math.abs(particle.vy) > vy) {
            particle.vy = particle.vy>0 ? vy: -vy;
        }
        particles_fireworks.push(particle);
    }
}

function Particle_fireworks() {
    this.w = this.h = Math.random()*4+1;
    this.x = xPoint-this.w/2;
    this.y = yPoint-this.h/2;
    this.vx = (Math.random()-0.5)*10;
    this.vy = (Math.random()-0.5)*10;
    this.alpha = Math.random()*.5+.5;
    this.color;
}

Particle_fireworks.prototype = {
    gravity: 0.05,
    move: function () {
        this.x += this.vx;
        this.vy += this.gravity;
        this.y += this.vy;
        this.alpha -= 0.01;
        if (this.x <= -this.w || this.x >= screen.width ||
            this.y >= screen.height ||
            this.alpha <= 0) {
            return false;
        }
        return true;
    },
    draw: function (c) {
        c.save();
        c.beginPath();
        c.translate(this.x+this.w/2, this.y+this.h/2);
        c.arc(0, 0, this.w, 0, Math.PI*2);
        c.fillStyle = this.color;
        c.globalAlpha = this.alpha;
        c.closePath();
        c.fill();
        c.restore();
    }
}

var COLORS, Confetti, NUM_CONFETTI, PI_2, canvas_confetti, confetti, context_confetti, drawCircle, i, range, resizeWindow_confetti, xpos=0.5, req_confetti;
NUM_CONFETTI = 350;
COLORS = [[85, 71, 106], [174, 61, 99], [219, 56, 83], [244, 92, 68], [248, 182, 70]];
PI_2 = 2 * Math.PI;
window.w = 0;
window.h = 0;

resizeWindow_confetti = function() {
    try {
        window.w = canvas_confetti.width = window.innerWidth;
        window.h = canvas_confetti.height = window.innerHeight;
    } catch (e) {}
};

window.addEventListener('resize', resizeWindow_confetti, false);

range = function(a, b) {
    return (b - a) * Math.random() + a;
};

drawCircle = function(x, y, r, style) {
    context_confetti.beginPath();
    context_confetti.arc(x, y, r, 0, PI_2, false);
    context_confetti.fillStyle = style;
    return context_confetti.fill();
};

window.requestAnimationFrame_confetti = (function() {
    return window.requestAnimationFrame || window.webkitRequestAnimationFrame || window.mozRequestAnimationFrame || window.oRequestAnimationFrame || window.msRequestAnimationFrame || function(callback) {
        return window.setTimeout(callback, 1000 / 60);
    };
})();

Confetti = class Confetti {
    constructor() {
        this.style = COLORS[~~range(0, 5)];
        this.rgb = `rgba(${this.style[0]},${this.style[1]},${this.style[2]}`;
        this.r = ~~range(2, 6);
        this.r2 = 2 * this.r;
        this.replace();
    }

    replace() {
        this.opacity = 0;
        this.dop = 0.03 * range(1, 4);
        this.x = range(-this.r2, w - this.r2);
        this.y = range(-20, h - this.r2);
        this.xmax = w - this.r;
        this.ymax = h - this.r;
        this.vx = range(0, 2) + 8 * xpos - 5;
        return this.vy = 0.7 * this.r + range(-1, 1);
    }

    draw() {
        var ref;
        this.x += this.vx;
        this.y += this.vy;
        this.opacity += this.dop;
        if (this.opacity > 1) {
            this.opacity = 1;
            this.dop *= -1;
        }
        if (this.opacity < 0 || this.y > this.ymax) {
            this.replace();
        }
        if (!((0 < (ref = this.x) && ref < this.xmax))) {
            this.x = (this.x + this.xmax) % this.xmax;
        }
        return drawCircle(~~this.x, ~~this.y, this.r, `${this.rgb},${this.opacity})`);
    }
};

confetti = (function() {
    var j, ref, results;
    results = [];
    for (i = j = 1, ref = NUM_CONFETTI; (1 <= ref ? j <= ref : j >= ref); i = 1 <= ref ? ++j : --j) {
        results.push(new Confetti());
    }
    return results;
})();

window.step_confetti = function() {
    var c, j, len, results;
    req_confetti = requestAnimationFrame_confetti(step_confetti);
    context_confetti.clearRect(0, 0, w, h);
    results = [];
    for (j = 0, len = confetti.length; j < len; j++) {
        c = confetti[j];
        results.push(c.draw());
    }
    return results;
};

function init_confetti() {
    canvas_confetti = document.getElementsByClassName("confetti_effect")[0];
    context_confetti = canvas_confetti.getContext("2d");
    setTimeout(resizeWindow_confetti, 0);
    step_confetti();
}


window.requestAnimFrame_sparkle = (function() {
    return window.requestAnimationFrame ||
        window.webkitRequestAnimationFrame ||
        window.mozRequestAnimationFrame ||
        window.oRequestAnimationFrame ||
        window.msRequestAnimationFrame ||
        function(callback) {
            window.setTimeout(callback, 1000 / 60);
        };
})();

var c_sparkle,ctx_sparkle,w_sparkle,h_sparkle,_w_sparkle,_h_sparkle, req_sparkle;
var arr_sparkle = [];
var cnt_sparkle = 0;

function init_sparkle() {
    c_sparkle = document.getElementsByClassName('sparkle_effect')[0];
    ctx_sparkle = c_sparkle.getContext('2d');
    w_sparkle = c_sparkle.width = window.innerWidth;
    h_sparkle = c_sparkle.height = window.innerHeight;
    _w_sparkle = w_sparkle * 0.5;
    _h_sparkle = h_sparkle * 0.5;
    resize_sparkle();
    anim_sparkle();
}

window.addEventListener('resize', resize_sparkle, false);

function resize_sparkle() {
    try {
        c_sparkle.width = w_sparkle = window.innerWidth;
        c_sparkle.height = h_sparkle = window.innerHeight;
        c_sparkle.style.position = 'absolute';
        c_sparkle.style.left = (window.innerWidth - w_sparkle) *
            .01 + 'px';
        c_sparkle.style.top = (window.innerHeight - h_sparkle) *
            .01 + 'px';
    } catch (e) {}
}

function anim_sparkle() {
    cnt_sparkle++;
    if (cnt_sparkle % 6) draw_sparkle();
    req_sparkle = window.requestAnimFrame_sparkle(anim_sparkle);
}

function draw_sparkle() {
    var splot = {
        x: rng(_w_sparkle - 900, _w_sparkle + 900),
        y: rng(_h_sparkle - 900, _h_sparkle + 900),
        r: rng(10, 60),
        spX: rng(-1, 1),
        spY: rng(-1, 1)
    };
    arr_sparkle.push(splot);
    while (arr_sparkle.length > 100) {
        arr_sparkle.shift();
    }
    ctx_sparkle.clearRect(0, 0, w_sparkle, h_sparkle);
    for (var i = 0; i < arr_sparkle.length; i++) {
        splot = arr_sparkle[i];;
        ctx_sparkle.fillStyle = rndCol();
        ctx_sparkle.beginPath();
        ctx_sparkle.arc(splot.x, splot.y, splot.r, 0, Math.PI * 2, true);
        ctx_sparkle.shadowBlur = 80;
        ctx_sparkle.shadowOffsetX = 2;
        ctx_sparkle.shadowOffsetY = 2;
        ctx_sparkle.shadowColor = rndCol();
        ctx_sparkle.globalCompositeOperation = 'lighter';
        ctx_sparkle.fill();
        splot.x = splot.x + splot.spX;
        splot.y = splot.y + splot.spY;
        splot.r = splot.r * 0.96;
    }
}

function rndCol() {
    var color = rng(230,255);
    var alpha = 0.3;
    var r = color;
    var g = color;
    var b = color;
    return "rgba(" + r + "," + g + "," + b + "," + alpha + ")";
}

function rng(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

const NUM_LOGO_CONFETTI = 30; // How many logos to display

var logo_confetti_particles = [],
    logo_confetti_canvas,
    logo_confetti_context,
    logo_confetti_mouse_x = 0.5, // Controls horizontal drift
    req_logo_confetti_frame,
    logo_confetti_image,
    logo_confetti_aspect_ratio; // Stores the image's width/height ratio

window.requestLogoConfettiAnimFrame = (function() {
    return window.requestAnimationFrame || window.webkitRequestAnimationFrame || window.mozRequestAnimationFrame || function(callback) {
        return window.setTimeout(callback, 1000 / 60);
    };
})();

class LogoConfettiParticle {
    constructor() {
        this.width = range(60,120);
        this.height = this.width / logo_confetti_aspect_ratio;
        this.angle = range(-0.1, 0.1); // Initial rotation
        this.spin = range(-0.001, 0.001); // Rotation speed
        this.replace();
    }

    replace() {
        this.opacity = 0.6;
        this.dop = 0.001 * range(0, 1); // Opacity change speed (fade in/out)
        this.x = range(-this.width, w - this.width);
        this.y = range(-90, 90 - this.height);
        this.xmax = w - this.width;
        this.ymax = h - this.height + 90;
        this.vx = range(-0.5, 0.5); // Horizontal velocity
        this.vy = range(1, 4); // Vertical velocity
    }

    draw() {
        this.x += this.vx;
        this.y += this.vy;
        this.angle += this.spin;
        this.opacity += this.dop;
        if (this.opacity > 1) {
            this.opacity = 1;
            this.dop *= -1; // Start fading out
        }
        if (this.opacity < 0 || this.y > this.ymax) {
            this.replace();
        }
        if (this.x > this.xmax) {
            this.x = -this.width;
        } else if (this.x < -this.width) {
            this.x = this.xmax;
        }
        logo_confetti_context.save();
        logo_confetti_context.globalAlpha = this.opacity;
        logo_confetti_context.translate(this.x + this.width / 2, this.y + this.height / 2);
        logo_confetti_context.rotate(this.angle);
        logo_confetti_context.drawImage(logo_confetti_image, -this.width / 2, -this.height / 2, this.width, this.height);
        logo_confetti_context.restore();
    }
}

const resize_logo_confetti_canvas = function() {
    try {
        window.w = logo_confetti_canvas.width = window.innerWidth;
        window.h = logo_confetti_canvas.height = window.innerHeight;
    } catch (e) {}
};

const animate_logo_confetti = function() {
    req_logo_confetti_frame = requestLogoConfettiAnimFrame(animate_logo_confetti);
    logo_confetti_context.clearRect(0, 0, w, h);
    for (const p of logo_confetti_particles) {
        p.draw();
    }
};

function init_logo_confetti() {
    if (window.logo_vt && window.logo_vt.trim() !== '') {
        logo_confetti_canvas = document.querySelector(".logo_confetti_effect");
        if (!logo_confetti_canvas) {
            console.error("Canvas element with class '.logo_confetti_effect' not found.");
            return;
        }
        logo_confetti_context = logo_confetti_canvas.getContext("2d");

        logo_confetti_image = new Image();
        logo_confetti_image.crossOrigin = "Anonymous";
        logo_confetti_image.onload = function() {
            logo_confetti_aspect_ratio = this.width / this.height;
            logo_confetti_particles = [];
            for (let i = 0; i < NUM_LOGO_CONFETTI; i++) {
                logo_confetti_particles.push(new LogoConfettiParticle());
            }
            window.addEventListener('resize', resize_logo_confetti_canvas, false);
            document.addEventListener('mousemove', function(e) {
                logo_confetti_mouse_x = e.pageX / window.w;
            });
            resize_logo_confetti_canvas();
            if (!req_logo_confetti_frame) {
                animate_logo_confetti();
            }
        };
        logo_confetti_image.src = window.logo_vt;
    }
};

function reset_effects() {
    window.cancelAnimationFrame(req_fireworks);
    window.cancelAnimationFrame(req_snow);
    window.cancelAnimationFrame(req_sparkle);
    window.cancelAnimationFrame(req_confetti);
    window.cancelAnimationFrame(req_logo_confetti_frame);
}


